# Capa: Rango de población 1
LAYER
  NAME "c_poblacion_1"
  STATUS ON
  TYPE POLYGON
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom, poblacion FROM marco_geoestadistico.poblacion WHERE poblacion>=1543 and poblacion<8925) AS t1 USING UNIQUE gid USING SRID=900913"

  METADATA
    "wms_title" "Rango de población 1"
    "wms_enable_request" "*"
  END

  CLASS
    NAME "Rango de población 1"
    STYLE
      COLOR 245 255 204
      OPACITY 60
      OUTLINECOLOR 60 60 60
      WIDTH 0.8
    END
  END
END
  
